1: // Package store persists devstack state in a local SQLite database. It owns the
2: // schema migrations and exposes typed CRUD helpers for the shared model types.
3: package store
4: 
5: import (
6: 	"context"
7: 	"database/sql"
8: 	"encoding/json"
9: 	"errors"
10: 	"fmt"
11: 	"net/url"
12: 	"os"
13: 	"path/filepath"
14: 	"runtime"
15: 	"time"
16: 
17: 	"github.com/AramZahedi/dev-web-stack/internal/model"
18: 
19: 	_ "modernc.org/sqlite" // pure-Go SQLite driver (no cgo)
20: )
21: 
22: // ErrNotFound is returned when a requested record does not exist.
23: var ErrNotFound = errors.New("not found")
24: 
25: // Store is a handle to the devstack SQLite database.
26: type Store struct {
27: 	db   *sql.DB
28: 	path string
29: 
30: 	// now is overridable in tests so backup retention can use deterministic
31: 	// timestamps. Production stores always use time.Now.
32: 	now func() time.Time
33: 
34: 	// migrations is overridable in tests to simulate a pending schema change
35: 	// without adding fake production migration files.
36: 	migrations []migration
37: }
38: 
39: // Open opens (and creates when needed) the SQLite database at path, applies the
40: // embedded migrations, and returns a ready store. The database uses a 5 second
41: // busy timeout, enforced foreign keys, and WAL journaling.
42: func Open(path string) (*Store, error) {
43: 	if path == "" {
44: 		return nil, errors.New("store: empty database path")
45: 	}
46: 	abs, err := filepath.Abs(path)
47: 	if err != nil {
48: 		return nil, fmt.Errorf("store: resolve database path %q: %w", path, err)
49: 	}
50: 
51: 	// The database contains site environment variables and PHP snapshots.
52: 	// Create it 0600 before SQLite opens it so the WAL/SHM siblings inherit
53: 	// owner-only permissions instead of the process umask.
54: 	if err := os.MkdirAll(filepath.Dir(abs), 0o700); err != nil {
55: 		return nil, fmt.Errorf("store: create database directory: %w", err)
56: 	}
57: 	f, err := os.OpenFile(abs, os.O_CREATE|os.O_RDWR, 0o600)
58: 	if err != nil {
59: 		return nil, fmt.Errorf("store: create database %s: %w", abs, err)
60: 	}
61: 	if err := f.Close(); err != nil {
62: 		return nil, fmt.Errorf("store: close database %s: %w", abs, err)
63: 	}
64: 	if err := os.Chmod(abs, 0o600); err != nil {
65: 		return nil, fmt.Errorf("store: set database permissions %s: %w", abs, err)
66: 	}
67: 	for _, suffix := range []string{"-wal", "-shm"} {
68: 		_ = os.Chmod(abs+suffix, 0o600)
69: 	}
70: 
71: 	// A Windows drive path must be a URI path component (/C:/...), not a URI
72: 	// authority. Otherwise SQLite parses "C:" as the host and rejects the DSN.
73: 	dsnPath := filepath.ToSlash(abs)
74: 	if runtime.GOOS == "windows" && len(dsnPath) >= 2 && dsnPath[1] == ':' {
75: 		dsnPath = "/" + dsnPath
76: 	}
77: 	dsn := url.URL{Scheme: "file", Path: dsnPath}
78: 	query := dsn.Query()
79: 	query.Add("_pragma", "busy_timeout(5000)")
80: 	query.Add("_pragma", "foreign_keys(1)")
81: 	query.Add("_pragma", "journal_mode(WAL)")
82: 	// Take the write lock when a transaction starts. This prevents two daemon
83: 	// or CLI processes from upgrading a read snapshot into a competing schema
84: 	// migration or a lost update.
85: 	query.Add("_txlock", "immediate")
86: 	dsn.RawQuery = query.Encode()
87: 
88: 	db, err := sql.Open("sqlite", dsn.String())
89: 	if err != nil {
90: 		return nil, fmt.Errorf("store: open %s: %w", abs, err)
91: 	}
92: 	// SQLite allows one writer at a time. Serialising access avoids
93: 	// SQLITE_BUSY between our own connections while the busy timeout covers
94: 	// other processes touching the same file.
95: 	db.SetMaxOpenConns(1)
96: 
97: 	s := &Store{db: db, path: abs}
98: 	if err := s.migrate(context.Background()); err != nil {
99: 		_ = db.Close()
100: 		return nil, fmt.Errorf("store: migrate %s: %w", abs, err)
101: 	}
102: 	return s, nil
103: }
