670: // ListEvents returns the most recent events first. A limit of zero or less
671: // returns all events.
672: func (s *Store) ListEvents(ctx context.Context, limit int) ([]model.Event, error) {
673: 	query := `SELECT id, site_id, type, message, created_at FROM events
674: 		ORDER BY created_at DESC, id DESC`
675: 	args := []any{}
676: 	if limit > 0 {
677: 		query += ` LIMIT ?`
678: 		args = append(args, limit)
679: 	}
680: 
681: 	rows, err := s.db.QueryContext(ctx, query, args...)
682: 	if err != nil {
683: 		return nil, fmt.Errorf("list events: %w", err)
684: 	}
685: 	defer func() {
686: 		_ = rows.Close()
687: 	}()
688: 
689: 	events := []model.Event{}
690: 	for rows.Next() {
691: 		var (
692: 			event     model.Event
693: 			createdAt int64
694: 		)
695: 		if err := rows.Scan(&event.ID, &event.SiteID, &event.Type, &event.Message, &createdAt); err != nil {
696: 			return nil, fmt.Errorf("list events: %w", err)
697: 		}
698: 		event.CreatedAt = time.Unix(createdAt, 0).UTC()
699: 		events = append(events, event)
700: 	}
701: 	if err := rows.Err(); err != nil {
702: 		return nil, fmt.Errorf("list events: %w", err)
703: 	}
704: 	return events, nil
705: }
