708: func siteInsertArgs(site model.Site) ([]any, error) {
709: 	phpExtensions, phpIni, env, phpFPM, err := marshalSiteFields(site)
710: 	if err != nil {
711: 		return nil, err
712: 	}
713: 	fcFile := site.FrontControllerFile
714: 	if fcFile == "" {
715: 		fcFile = "index.php"
716: 	}
717: 	fcMode := site.FrontControllerMode
718: 	if fcMode == "" {
719: 		fcMode = "auto"
720: 	}
721: 	override := site.ApacheAllowOverride
722: 	if override == "" {
