724: 	}
725: 	spaFile := site.SPAFallbackFile
726: 	if spaFile == "" {
727: 		spaFile = "index.html"
728: 	}
729: 	buildJSON := "{}"
730: 	if site.Build != nil {
731: 		b, err := json.Marshal(site.Build)
732: 		if err != nil {
733: 			return nil, fmt.Errorf("encode site %q build: %w", site.ID, err)
734: 		}
735: 		buildJSON = string(b)
736: 	}
737: 	return []any{
738: 		site.ID, site.Name, site.Domain, boolInt(site.WWW), string(site.Backend),
739: 		site.HostPath, site.BackendPath, string(site.Kind), site.PHPVersion,
740: 		phpExtensions, phpIni, site.PHPBuild, site.PHPIniRaw, site.PHPConfigHash,
741: 		site.NodeVersion, site.Command, env,
742: 		site.DocumentRoot, boolInt(site.FrontController), boolInt(site.SPAFallback),
743: 		boolInt(site.TLS), boolInt(site.ForceHTTPS), string(site.DesiredState),
744: 		string(site.Status), site.HTTPPort, site.FastCGIPort,
745: 		site.CreatedAt.Unix(), site.UpdatedAt.Unix(),
746: 		fcFile, fcMode, override, spaFile, buildJSON, phpFPM, string(normalizedSourceMode(site.SourceMode)),
747: 	}, nil
748: }
