757: // marshalSiteFields encodes the site's JSON columns.
758: func marshalSiteFields(site model.Site) (phpExtensions, phpIni, env, phpFPM string, err error) {
759: 	if phpExtensions, err = marshalJSON(site.PHPExtensions); err != nil {
760: 		return "", "", "", "", fmt.Errorf("encode site %q php extensions: %w", site.ID, err)
761: 	}
762: 	if phpIni, err = marshalJSON(site.PHPIni); err != nil {
763: 		return "", "", "", "", fmt.Errorf("encode site %q php ini: %w", site.ID, err)
764: 	}
765: 	if env, err = marshalJSON(site.Env); err != nil {
766: 		return "", "", "", "", fmt.Errorf("encode site %q env: %w", site.ID, err)
767: 	}
768: 	budget := site.PHPFPM
769: 	if budget == nil || budget.IsZero() {
770: 		phpFPM = "{}"
771: 	} else if phpFPM, err = marshalJSON(budget); err != nil {
772: 		return "", "", "", "", fmt.Errorf("encode site %q php fpm: %w", site.ID, err)
773: 	}
774: 	return phpExtensions, phpIni, env, phpFPM, nil
775: }
