790: // scanSite decodes one site row. label/value identify the row in error
791: // messages; both are empty for list scans.
792: func scanSite(scanner rowScanner, label, value string) (model.Site, error) {
793: 	var (
794: 		site                              model.Site
795: 		www, frontController, spaFallback int
796: 		tlsEnabled, forceHTTPS            int
797: 		phpExtensions, phpIni, env        string
798: 		createdAt, updatedAt              int64
799: 		buildJSON, phpFPM                 string
800: 	)
801: 	err := scanner.Scan(
802: 		&site.ID, &site.Name, &site.Domain, &www, &site.Backend, &site.HostPath,
803: 		&site.BackendPath, &site.Kind, &site.PHPVersion, &phpExtensions, &phpIni,
804: 		&site.PHPBuild, &site.PHPIniRaw, &site.PHPConfigHash,
805: 		&site.NodeVersion, &site.Command, &env, &site.DocumentRoot,
806: 		&frontController, &spaFallback, &tlsEnabled, &forceHTTPS,
807: 		&site.DesiredState, &site.Status, &site.HTTPPort, &site.FastCGIPort,
808: 		&createdAt, &updatedAt,
809: 		&site.FrontControllerFile, &site.FrontControllerMode,
810: 		&site.ApacheAllowOverride, &site.SPAFallbackFile, &buildJSON, &phpFPM,
811: 		&site.SourceMode,
812: 	)
813: 	if err != nil {
814: 		if label != "" && errors.Is(err, sql.ErrNoRows) {
815: 			return model.Site{}, ErrNotFound
816: 		}
817: 		if label != "" {
818: 			return model.Site{}, fmt.Errorf("get site by %s %q: %w", label, value, err)
819: 		}
820: 		return model.Site{}, err
821: 	}
822: 
823: 	site.WWW = www != 0
824: 	site.FrontController = frontController != 0
825: 	site.SPAFallback = spaFallback != 0
826: 	site.TLS = tlsEnabled != 0
827: 	site.ForceHTTPS = forceHTTPS != 0
828: 	site.CreatedAt = time.Unix(createdAt, 0).UTC()
829: 	site.UpdatedAt = time.Unix(updatedAt, 0).UTC()
830: 
831: 	if site.FrontControllerFile == "" {
832: 		site.FrontControllerFile = "index.php"
833: 	}
834: 	if site.FrontControllerMode == "" {
835: 		site.FrontControllerMode = "auto"
836: 	}
837: 	if site.ApacheAllowOverride == "" {
838: 		site.ApacheAllowOverride = "all"
839: 	}
840: 	if site.SPAFallbackFile == "" {
841: 		site.SPAFallbackFile = "index.html"
842: 	}
843: 
844: 	if err := json.Unmarshal([]byte(phpExtensions), &site.PHPExtensions); err != nil {
845: 		return model.Site{}, fmt.Errorf("decode site %q php extensions: %w", site.ID, err)
846: 	}
847: 	if err := json.Unmarshal([]byte(phpIni), &site.PHPIni); err != nil {
848: 		return model.Site{}, fmt.Errorf("decode site %q php ini: %w", site.ID, err)
849: 	}
850: 	if err := json.Unmarshal([]byte(env), &site.Env); err != nil {
851: 		return model.Site{}, fmt.Errorf("decode site %q env: %w", site.ID, err)
852: 	}
853: 	if buildJSON != "" && buildJSON != "{}" && buildJSON != "null" {
854: 		var profile model.BuildProfile
855: 		if err := json.Unmarshal([]byte(buildJSON), &profile); err != nil {
856: 			return model.Site{}, fmt.Errorf("decode site %q build: %w", site.ID, err)
857: 		}
858: 		if profile.NodeVersion != "" || profile.Command != "" || profile.Output != "" || len(profile.Env) > 0 {
859: 			site.Build = &profile
860: 		}
861: 	}
862: 	if phpFPM != "" && phpFPM != "null" {
863: 		var budget model.PHPFPMBudget
