72: // poolSizing resolves a persisted budget against the conservative defaults.
73: // Small explicit maxima can make a default spare count larger than the pool,
74: // so the resolved values are clamped before they reach php-fpm.
75: func poolSizing(pool *model.PHPFPMBudget) (mode string, maxChildren, startServers, minSpare, maxSpare, backlog int) {
76: 	mode = "dynamic"
77: 	maxChildren, startServers, minSpare, maxSpare = 5, 2, 1, 3
78: 	explicitStart, explicitMin, explicitMax := false, false, false
79: 	if pool != nil {
80: 		if pool.Mode != "" {
81: 			mode = pool.Mode
82: 		}
83: 		if pool.MaxChildren > 0 {
84: 			maxChildren = pool.MaxChildren
85: 		}
86: 		if pool.StartServers > 0 {
87: 			startServers, explicitStart = pool.StartServers, true
88: 		}
89: 		if pool.MinSpareServers > 0 {
90: 			minSpare, explicitMin = pool.MinSpareServers, true
91: 		}
92: 		if pool.MaxSpareServers > 0 {
93: 			maxSpare, explicitMax = pool.MaxSpareServers, true
94: 		}
95: 		backlog = pool.ListenBacklog
96: 	}
97: 	if mode == "static" {
98: 		return mode, maxChildren, 0, 0, 0, backlog
99: 	}
100: 	// Fill omitted bounds around the values that were supplied. Validation has
101: 	// already rejected an explicitly inconsistent set; this keeps partial
102: 	// budgets valid without inventing a second contract for callers.
103: 	if !explicitMin {
104: 		minSpare = 1
105: 	}
106: 	if !explicitMax {
107: 		maxSpare = max(3, minSpare, startServers)
108: 	}
109: 	if !explicitStart {
110: 		startServers = min(max(2, minSpare), maxSpare)
111: 	}
112: 	if startServers > maxChildren {
113: 		startServers = maxChildren
114: 	}
115: 	if minSpare > maxChildren {
116: 		minSpare = maxChildren
117: 	}
118: 	if maxSpare < minSpare {
119: 		maxSpare = minSpare
120: 	}
121: 	if maxSpare > maxChildren {
122: 		maxSpare = maxChildren
123: 	}
124: 	if startServers > maxSpare {
125: 		startServers = maxSpare
126: 	}
127: 	return mode, maxChildren, startServers, minSpare, maxSpare, backlog
128: }
