package databases

import (
	"context"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/AramZahedi/dev-web-stack/internal/model"
	"github.com/AramZahedi/dev-web-stack/internal/store"
)

// CreateBackup starts a logical backup and records its job and metadata.
func (m *Manager) CreateBackup(ctx context.Context, serviceID, database string, req CreateBackupRequest) (model.DatabaseJob, error) {
	serviceID = canonicalServiceID(serviceID)
	database = strings.TrimSpace(database)
	if database == "" {
		return model.DatabaseJob{}, fmt.Errorf("%w: database is required", ErrInvalidRequest)
	}
	if _, err := m.requireActive(ctx, serviceID); err != nil {
		return model.DatabaseJob{}, err
	}
	unlock := m.lockService(serviceID)
	defer unlock()

	if req.Kind == "" {
		req.Kind = model.BackupManual
	}
	record := m.newJobRecord(serviceID, database, model.JobBackup)
	return m.executeJob(ctx, record, func(jobCtx context.Context) (model.DatabaseJob, error) {
		return m.deps.Platform.CreateBackup(jobCtx, serviceID, database, req)
	}, req.Kind)
}

// RestoreBackup restores a backup to a new or existing target. An overwrite
// requires typed confirmation and a stopped-site check. A pre-restore backup
// is created first when requested.
func (m *Manager) RestoreBackup(ctx context.Context, serviceID, backupID string, req RestoreBackupRequest) (model.DatabaseJob, error) {
	serviceID = canonicalServiceID(serviceID)
	if _, err := m.requireActive(ctx, serviceID); err != nil {
		return model.DatabaseJob{}, err
	}
	backup, err := m.backupRecord(ctx, serviceID, backupID)
	if err != nil {
		return model.DatabaseJob{}, err
	}
	target := strings.TrimSpace(req.Target)
	if target == "" {
		target = fmt.Sprintf("%s_restore_%s", backup.DatabaseName, m.now().Format("20060102-150405"))
	}
	req.Target = target
	if req.Overwrite {
		if strings.TrimSpace(req.Confirm) != target {
			return model.DatabaseJob{}, fmt.Errorf("%w: type %q to confirm the overwrite", ErrConflict, target)
		}
		if err := m.ensureLinkedSitesStopped(ctx, serviceID, target); err != nil {
			return model.DatabaseJob{}, err
		}
	}
	unlock := m.lockService(serviceID)
	defer unlock()

	preBackupID := ""
	if req.PreRestoreBackup {
		preJob, err := m.CreateBackup(ctx, serviceID, target, CreateBackupRequest{Kind: model.BackupPreRestore})
		if err != nil {
			return m.failedJobRecord(serviceID, target, model.JobRestore, "", fmt.Errorf("pre-restore backup: %w", err))
		}
		if preJob.Status != model.JobSucceeded || preJob.BackupID == "" {
			return m.failedJobRecord(serviceID, target, model.JobRestore, "", fmt.Errorf("pre-restore backup did not succeed: %s", preJob.Message))
		}
		preBackupID = preJob.BackupID
	}

	record := m.newJobRecord(serviceID, target, model.JobRestore)
	record.BackupID = preBackupID
	return m.executeJob(ctx, record, func(jobCtx context.Context) (model.DatabaseJob, error) {
		return m.deps.Platform.RestoreBackup(jobCtx, serviceID, backupID, req)
	}, model.BackupPreRestore)
}

// ImportDatabase imports SQL into an existing database. Replace mode requires
// typed confirmation and a stopped-site check; a pre-import backup is optional.
func (m *Manager) ImportDatabase(ctx context.Context, serviceID, database string, file io.Reader, filename string, req ImportRequest) (model.DatabaseJob, error) {
	serviceID = canonicalServiceID(serviceID)
	database = strings.TrimSpace(database)
	if database == "" {
		return model.DatabaseJob{}, fmt.Errorf("%w: database is required", ErrInvalidRequest)
	}
	if req.Mode == "" {
		req.Mode = ImportMerge
	}
	if req.Mode != ImportMerge && req.Mode != ImportReplace {
		return model.DatabaseJob{}, fmt.Errorf("%w: import mode %q", ErrInvalidRequest, req.Mode)
	}
	if _, err := m.requireActive(ctx, serviceID); err != nil {
		return model.DatabaseJob{}, err
	}
	if req.Mode == ImportReplace {
		if strings.TrimSpace(req.Confirm) != database {
			return model.DatabaseJob{}, fmt.Errorf("%w: type %q to confirm replacing the database contents", ErrConflict, database)
		}
		if err := m.ensureLinkedSitesStopped(ctx, serviceID, database); err != nil {
			return model.DatabaseJob{}, err
		}
	}
	unlock := m.lockService(serviceID)
	defer unlock()

	preBackupID := ""
	if req.PreImportBackup {
		preJob, err := m.CreateBackup(ctx, serviceID, database, CreateBackupRequest{Kind: model.BackupPreImport})
		if err != nil {
			return m.failedJobRecord(serviceID, database, model.JobImport, "", fmt.Errorf("pre-import backup: %w", err))
		}
		if preJob.Status != model.JobSucceeded || preJob.BackupID == "" {
			return m.failedJobRecord(serviceID, database, model.JobImport, "", fmt.Errorf("pre-import backup did not succeed: %s", preJob.Message))
		}
		preBackupID = preJob.BackupID
	}

	record := m.newJobRecord(serviceID, database, model.JobImport)
	record.BackupID = preBackupID
	return m.executeJob(ctx, record, func(jobCtx context.Context) (model.DatabaseJob, error) {
		return m.deps.Platform.ImportDatabase(jobCtx, serviceID, database, file, filename, req)
	}, model.BackupPreImport)
}

// newJobRecord creates a queued job row.
func (m *Manager) newJobRecord(serviceID, database string, kind model.DatabaseJobKind) model.DatabaseJobRecord {
	now := m.now().Unix()
	record := model.DatabaseJobRecord{
		ID:           m.newID("job"),
		ServiceID:    serviceID,
		DatabaseName: database,
		Kind:         string(kind),
		Status:       string(model.JobQueued),
		CreatedAt:    now,
		UpdatedAt:    now,
	}
	_ = m.deps.Store.CreateDatabaseJob(context.Background(), record)
	return record
}

// failedJobRecord creates and persists a failed job without calling the
// platform. It is used when a pre-operation backup cannot be made.
func (m *Manager) failedJobRecord(serviceID, database string, kind model.DatabaseJobKind, backupID string, cause error) (model.DatabaseJob, error) {
	record := m.newJobRecord(serviceID, database, kind)
	record.Status = string(model.JobFailed)
	record.BackupID = backupID
	record.Message = safeErrorMessage(cause)
	record.UpdatedAt = m.now().Unix()
	_ = m.deps.Store.UpdateDatabaseJob(context.Background(), record)
	job := recordToJob(record)
	m.auditJob(context.Background(), job, "failed")
	return job, cause
}

// executeJob runs one platform operation while tracking its queued/running/
// terminal states. Platform calls may themselves be asynchronous; a completed
// platform job is recorded as succeeded, a failed one as failed.
func (m *Manager) executeJob(ctx context.Context, record model.DatabaseJobRecord, fn func(context.Context) (model.DatabaseJob, error), backupKind model.DatabaseBackupKind) (model.DatabaseJob, error) {
	jobCtx, cancel := context.WithCancel(ctx)
	m.jobsMu.Lock()
	m.cancels[record.ID] = cancel
	m.jobsMu.Unlock()
	defer func() {
		cancel()
		m.jobsMu.Lock()
		delete(m.cancels, record.ID)
		m.jobsMu.Unlock()
	}()

	record.Status = string(model.JobRunning)
	record.UpdatedAt = m.now().Unix()
	if err := m.deps.Store.UpdateDatabaseJob(ctx, record); err != nil {
		return recordToJob(record), err
	}
	job := recordToJob(record)
	m.emit(ctx, "", "database.job.updated", fmt.Sprintf("database job %s running", job.ID))

	result, err := fn(jobCtx)
	if result.ID != "" {
		m.jobsMu.Lock()
		m.platformJobs[record.ID] = result.ID
		m.jobsMu.Unlock()
	}
	if result.Status != "" {
		job.Status = result.Status
	}
	if result.Progress > 0 {
		job.Progress = result.Progress
	}
	if result.Message != "" {
		job.Message = result.Message
	}
	if result.BackupID != "" {
		job.BackupID = result.BackupID
	}
	if err != nil || job.Status == model.JobFailed {
		if errors.Is(jobCtx.Err(), context.Canceled) {
			job.Status = model.JobCanceled
		} else {
			job.Status = model.JobFailed
			if job.Message == "" {
				job.Message = safeErrorMessage(err)
			}
		}
		job.UpdatedAt = m.now()
		record = jobToRecord(job)
		_ = m.deps.Store.UpdateDatabaseJob(context.Background(), record)
		m.emit(context.Background(), "", "database.job.updated", fmt.Sprintf("database job %s %s", job.ID, job.Status))
		m.auditJob(context.Background(), job, string(job.Status))
		if err == nil {
			err = fmt.Errorf("%w: database job %s %s: %s", ErrConflict, job.ID, job.Status, job.Message)
		}
		return job, err
	}
	if job.Status == "" || job.Status == model.JobRunning || job.Status == model.JobQueued {
		job.Status = model.JobSucceeded
	}
	job.Progress = 100
	job.UpdatedAt = m.now()
	record = jobToRecord(job)
	_ = m.deps.Store.UpdateDatabaseJob(context.Background(), record)
	if job.BackupID != "" {
		m.recordBackupMetadata(ctx, record.ServiceID, record.DatabaseName, job.BackupID, backupKind)
	}
	m.emit(context.Background(), "", "database.job.updated", fmt.Sprintf("database job %s succeeded", job.ID))
	m.auditJob(context.Background(), job, "ok")
	return job, nil
}

// auditJob writes the durable audit row for one terminal job state.
func (m *Manager) auditJob(ctx context.Context, job model.DatabaseJob, result string) {
	action := "database.job.updated"
	switch job.Kind {
	case model.JobBackup:
		action = "database.backup.created"
	case model.JobRestore:
		action = "database.backup.restored"
	case model.JobImport:
		action = "database.import.completed"
	}
	detail := map[string]any{"job_id": job.ID, "kind": string(job.Kind), "status": string(job.Status)}
	if job.BackupID != "" {
		detail["backup_id"] = job.BackupID
	}
	m.audit(ctx, action, job.ServiceID, "", "database", job.Database, result, detail)
}

// recordBackupMetadata persists the platform's backup view. When the platform
// does not return metadata for a just-created backup, a minimal ready record is
// stored so the backup remains addressable.
func (m *Manager) recordBackupMetadata(ctx context.Context, serviceID, database, backupID string, kind model.DatabaseBackupKind) {
	backups, err := m.deps.Platform.ListBackups(ctx, serviceID)
	if err == nil {
		for _, backup := range backups {
			if backup.ID != backupID {
				continue
			}
			record := backupFromView(backup)
			if _, getErr := m.deps.Store.GetDatabaseBackup(ctx, backupID); errors.Is(getErr, store.ErrNotFound) {
				_ = m.deps.Store.CreateDatabaseBackup(ctx, record)
			} else if getErr == nil {
				_ = m.deps.Store.UpdateDatabaseBackup(ctx, record)
			}
			return
		}
	}
	record := model.DatabaseBackupRecord{
		ID:           backupID,
		ServiceID:    serviceID,
		Engine:       engineForService(serviceID),
		DatabaseName: database,
		Kind:         string(kind),
		Status:       string(model.BackupReady),
		CreatedAt:    m.now().Unix(),
	}
	if _, getErr := m.deps.Store.GetDatabaseBackup(ctx, backupID); errors.Is(getErr, store.ErrNotFound) {
		_ = m.deps.Store.CreateDatabaseBackup(ctx, record)
	}
}

// backupRecord resolves a backup from metadata, falling back to the platform
// inventory for backups created outside this daemon process.
func (m *Manager) backupRecord(ctx context.Context, serviceID, backupID string) (model.DatabaseBackupRecord, error) {
	record, err := m.deps.Store.GetDatabaseBackup(ctx, backupID)
	if err == nil {
		return record, nil
	}
	if !errors.Is(err, store.ErrNotFound) {
		return model.DatabaseBackupRecord{}, err
	}
	backups, listErr := m.deps.Platform.ListBackups(ctx, serviceID)
	if listErr != nil {
		return model.DatabaseBackupRecord{}, listErr
	}
	for _, backup := range backups {
		if backup.ID == backupID {
			record = backupFromView(backup)
			_ = m.deps.Store.CreateDatabaseBackup(ctx, record)
			return record, nil
		}
	}
	return model.DatabaseBackupRecord{}, fmt.Errorf("%w: backup %q", ErrNotFound, backupID)
}

package databases

import (
	"context"
	"errors"
	"fmt"
	"net/url"
	"regexp"
	"sort"
	"strings"

	"github.com/AramZahedi/dev-web-stack/internal/model"
	"github.com/AramZahedi/dev-web-stack/internal/services"
	"github.com/AramZahedi/dev-web-stack/internal/store"
)

var envSlugPattern = regexp.MustCompile(`[^A-Z0-9]+`)

// ListSiteLinks returns every database link for a site with live connection
// details. A stopped service or externally dropped database is reported as
// unavailable rather than failing the whole list.
func (m *Manager) ListSiteLinks(ctx context.Context, siteRef string) ([]model.DatabaseLink, error) {
	site, err := m.resolveSite(ctx, siteRef)
	if err != nil {
		return nil, err
	}
	records, err := m.deps.Store.ListDatabaseLinksBySite(ctx, site.ID)
	if err != nil {
		return nil, err
	}
	databasesByService := make(map[string]map[string]model.Database)
	views := make(map[string]services.View)
	for _, record := range records {
		serviceID := canonicalServiceID(record.ServiceID)
		if _, ok := views[serviceID]; !ok {
			view, viewErr := m.serviceView(ctx, serviceID)
			if viewErr == nil {
				views[serviceID] = view
			}
		}
		view, serviceKnown := views[serviceID]
		if serviceKnown && view.Active {
			if _, ok := databasesByService[serviceID]; !ok {
				list, listErr := m.deps.Platform.ListDatabases(ctx, serviceID)
				if listErr != nil {
					return nil, listErr
				}
				byName := make(map[string]model.Database, len(list))
				for _, database := range list {
					byName[database.Name] = database
				}
				databasesByService[serviceID] = byName
			}
		}
	}
	links := make([]model.DatabaseLink, 0, len(records))
	for _, record := range records {
		link, _ := m.buildLink(ctx, record, views, databasesByService)
		links = append(links, link)
	}
	sort.SliceStable(links, func(i, j int) bool {
		if links[i].Primary != links[j].Primary {
			return links[i].Primary
		}
		return links[i].Database < links[j].Database
	})
	return links, nil
}

// buildLink assembles one link view. Errors are reported on the link rather
// than failing the list.
func (m *Manager) buildLink(ctx context.Context, record model.DatabaseLinkRecord, views map[string]services.View, databases map[string]map[string]model.Database) (model.DatabaseLink, error) {
	serviceID := canonicalServiceID(record.ServiceID)
	engine := engineForService(serviceID)
	link := model.DatabaseLink{
		ID:        record.ID,
		SiteID:    record.SiteID,
		SiteName:  record.SiteName,
		ServiceID: serviceID,
		Engine:    engine,
		Database:  record.DatabaseName,
		UserID:    record.UserID,
		Primary:   record.Primary,
	}
	var problems []string
	user, userErr := m.deps.Store.GetDatabaseUser(ctx, record.UserID)
	if userErr != nil {
		problems = append(problems, "database user no longer exists")
	} else {
		link.Username = user.Username
		link.Host = user.Host
		link.PasswordManaged = user.PasswordManaged
	}
	view, serviceKnown := views[serviceID]
	if !serviceKnown {
		problems = append(problems, "database service is not installed")
	} else if !view.Active {
		problems = append(problems, "database service is not active")
	}
	if serviceKnown && view.Active {
		byName, listed := databases[serviceID]
		if listed {
			if _, ok := byName[record.DatabaseName]; !ok {
				problems = append(problems, "database no longer exists")
			}
		}
	}
	port := defaultServicePort(engine)
	if serviceKnown {
		port = servicePort(view, engine)
	}
	link.Connection = model.DatabaseConnection{
		Engine:          engine,
		Host:            "127.0.0.1",
		Port:            port,
		Database:        record.DatabaseName,
		Username:        link.Username,
		PasswordManaged: link.PasswordManaged,
	}
	link.Connection.Env = metadataEnv(link)
	if link.PasswordManaged && link.Username != "" {
		scheme := connectionScheme(engine)
		if scheme != "" {
			link.Connection.URL = (&url.URL{
				Scheme: scheme,
				User:   url.User(link.Username),
				Host:   fmt.Sprintf("127.0.0.1:%d", port),
				Path:   "/" + record.DatabaseName,
			}).String()
		}
	}
	link.Available = len(problems) == 0
	if len(problems) > 0 {
		link.Error = strings.Join(problems, "; ")
	}
	return link, nil
}

// LinkDatabase links an existing site to an existing database/user. It never
// grants access automatically; a missing grant is surfaced as a warning.
func (m *Manager) LinkDatabase(ctx context.Context, siteRef string, req LinkDatabaseRequest) (model.DatabaseLink, error) {
	site, err := m.resolveSite(ctx, siteRef)
	if err != nil {
		return model.DatabaseLink{}, err
	}
	serviceID := canonicalServiceID(req.ServiceID)
	if isRedisService(serviceID) {
		return model.DatabaseLink{}, fmt.Errorf("%w: Redis users cannot be linked to sites", ErrUnsupported)
	}
	if _, err := m.requireActive(ctx, serviceID); err != nil {
		return model.DatabaseLink{}, err
	}
	database := strings.TrimSpace(req.Database)
	if database == "" {
		return model.DatabaseLink{}, fmt.Errorf("%w: database is required", ErrInvalidRequest)
	}
	user, err := m.deps.Store.GetDatabaseUser(ctx, req.UserID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return model.DatabaseLink{}, fmt.Errorf("%w: user %q", ErrNotFound, req.UserID)
		}
		return model.DatabaseLink{}, err
	}
	if canonicalServiceID(user.ServiceID) != serviceID {
		return model.DatabaseLink{}, fmt.Errorf("%w: user %q does not belong to service %q", ErrInvalidRequest, user.Username, serviceID)
	}
	if strings.TrimSpace(req.Password) != "" {
		return model.DatabaseLink{}, fmt.Errorf("%w: the platform contract cannot store an external password; create a metadata-only link and set the password in the engine", ErrUnsupported)
	}
	if err := m.ensureDatabaseExists(ctx, serviceID, database); err != nil {
		return model.DatabaseLink{}, err
	}
	unlock := m.lockService(serviceID)
	defer unlock()

	records, err := m.deps.Store.ListDatabaseLinksBySite(ctx, site.ID)
	if err != nil {
		return model.DatabaseLink{}, err
	}
	primary := req.Primary
	if len(records) == 0 {
		primary = true
	}
	for _, record := range records {
		if canonicalServiceID(record.ServiceID) == serviceID && record.DatabaseName == database {
			return model.DatabaseLink{}, fmt.Errorf("%w: database %q is already linked to site %q", ErrConflict, database, site.Name)
		}
	}
	record := model.DatabaseLinkRecord{
		ID:           m.newID("lnk"),
		SiteID:       site.ID,
		SiteName:     site.Name,
		ServiceID:    serviceID,
		DatabaseName: database,
		UserID:       user.ID,
		Primary:      primary,
		CreatedAt:    m.now().Unix(),
	}
	if err := m.deps.Store.CreateDatabaseLink(ctx, record); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return model.DatabaseLink{}, fmt.Errorf("%w: database %q is already linked to site %q", ErrConflict, database, site.Name)
		}
		return model.DatabaseLink{}, err
	}
	if primary {
		if err := m.deps.Store.SetPrimaryDatabaseLink(ctx, site.ID, record.ID); err != nil {
			return model.DatabaseLink{}, err
		}
	}
	link := m.linkFromRecord(ctx, record, user)
	if !userHasGrant(user, database) {
		link.Error = "database user has no grant on this database"
	}
	m.audit(ctx, "database.link.changed", serviceID, site.ID, "database_link", database, "ok", map[string]any{"link_id": record.ID, "user_id": user.ID, "primary": primary})
	m.emit(ctx, site.ID, "database.link.changed", fmt.Sprintf("site %s linked to database %s on %s", site.Name, database, serviceID))
	return link, nil
}

// UnlinkDatabase deletes only the link. Database, user, grants, passwords, and
// backups are untouched.
func (m *Manager) UnlinkDatabase(ctx context.Context, siteRef, linkID string) error {
	site, err := m.resolveSite(ctx, siteRef)
	if err != nil {
		return err
	}
	record, err := m.deps.Store.GetDatabaseLink(ctx, linkID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return fmt.Errorf("%w: link %q", ErrNotFound, linkID)
		}
		return err
	}
	if record.SiteID != site.ID {
		return fmt.Errorf("%w: link %q does not belong to site %q", ErrNotFound, linkID, site.Name)
	}
	if err := m.deps.Store.DeleteDatabaseLink(ctx, linkID); err != nil {
		return err
	}
	m.audit(ctx, "database.link.changed", canonicalServiceID(record.ServiceID), site.ID, "database_link", record.DatabaseName, "ok", map[string]any{"link_id": linkID, "unlinked": true})
	m.emit(ctx, site.ID, "database.link.changed", fmt.Sprintf("site %s unlinked from database %s", site.Name, record.DatabaseName))
	return nil
}

// SiteDatabaseEnv resolves the environment for every link of a site. Managed
// links are resolved by the privileged platform; metadata-only links use the
// safe daemon-side values. The returned map may contain secrets and must never
// be persisted or logged.
func (m *Manager) SiteDatabaseEnv(ctx context.Context, siteRef string) (map[string]string, error) {
	site, err := m.resolveSite(ctx, siteRef)
	if err != nil {
		return nil, err
	}
	links, err := m.ListSiteLinks(ctx, site.ID)
	if err != nil {
		return nil, err
	}
	m.audit(ctx, "database.env.resolved", "", site.ID, "site", site.Name, "ok", nil)
	if len(links) == 0 {
		return map[string]string{}, nil
	}
	allMetadataOnly := true
	for _, link := range links {
		if link.PasswordManaged {
			allMetadataOnly = false
			break
		}
	}
	if allMetadataOnly {
		return SiteEnv(links)
	}
	grouped := make(map[string][]model.DatabaseLink)
	for _, link := range links {
		serviceID := canonicalServiceID(link.ServiceID)
		grouped[serviceID] = append(grouped[serviceID], link)
	}
	env := map[string]string{}
	for serviceID, serviceLinks := range grouped {
		resolved, err := m.deps.Platform.ResolveSiteEnv(ctx, serviceID, serviceLinks)
		if err != nil {
			return nil, err
		}
		for key, value := range resolved {
			env[key] = value
		}
	}
	return env, nil
}

// GuardSite blocks a site start only when a different member of an exclusive
// engine group is active. A stopped exact service is a visible warning.
func (m *Manager) GuardSite(ctx context.Context, site model.Site) error {
	records, err := m.deps.Store.ListDatabaseLinksBySite(ctx, site.ID)
	if err != nil {
		return err
	}
	if len(records) == 0 {
		return nil
	}
	views, err := m.deps.Services.List(ctx)
	if err != nil {
		return err
	}
	byID := make(map[services.ID]services.View, len(views))
	for _, view := range views {
		byID[view.ID] = view
	}
	for _, record := range records {
		serviceID := services.ID(canonicalServiceID(record.ServiceID))
		view, ok := byID[serviceID]
		if !ok {
			m.emit(ctx, site.ID, "database.service.offline", fmt.Sprintf("site %s: database service %s is not installed", site.Name, serviceID))
			continue
		}
		if view.Active {
			continue
		}
		for _, other := range views {
			if other.ID == view.ID || !other.Active {
				continue
			}
			if view.Group != "" && other.Group == view.Group && view.Group.Exclusive() {
				return fmt.Errorf("%w: site %s links %s but %s is active on the same exclusive port group; deactivate %s or switch the link", ErrConflict, site.Name, serviceID, other.ID, other.ID)
			}
		}
		m.emit(ctx, site.ID, "database.service.offline", fmt.Sprintf("site %s: database service %s is stopped", site.Name, serviceID))
	}
	return nil
}

// DeleteServiceLinks removes every link to a service after an uninstall with
// delete-data succeeded. It never touches databases, users, or backups.
func (m *Manager) DeleteServiceLinks(ctx context.Context, serviceID string) error {
	serviceID = canonicalServiceID(serviceID)
	removed, err := m.deps.Store.DeleteDatabaseLinksByService(ctx, serviceID)
	if err != nil {
		return err
	}
	if removed > 0 {
		m.audit(ctx, "database.link.changed", serviceID, "", "database_link", serviceID, "ok", map[string]any{"removed": removed})
		m.emit(ctx, "", "database.link.changed", fmt.Sprintf("removed %d site links to service %s after uninstall", removed, serviceID))
	}
	return nil
}

// ensureLinkedSitesStopped blocks destructive database operations while a
// linked site is running.
func (m *Manager) ensureLinkedSitesStopped(ctx context.Context, serviceID, database string) error {
	records, err := m.deps.Store.ListDatabaseLinksByService(ctx, canonicalServiceID(serviceID))
	if err != nil {
		return err
	}
	var running []string
	for _, record := range records {
		if record.DatabaseName != database {
			continue
		}
		site, err := m.deps.Sites.GetSite(ctx, record.SiteID)
		if err != nil {
			if errors.Is(err, store.ErrNotFound) {
				continue
			}
			return err
		}
		if site.Status == model.StatusRunning || site.DesiredState == model.DesiredRunning {
			running = append(running, site.Name)
		}
	}
	if len(running) > 0 {
		sort.Strings(running)
		return fmt.Errorf("%w: stop linked sites first: %s", ErrConflict, strings.Join(running, ", "))
	}
	return nil
}

// ensureDatabaseExists verifies a database name against the live engine.
func (m *Manager) ensureDatabaseExists(ctx context.Context, serviceID, database string) error {
	databases, err := m.deps.Platform.ListDatabases(ctx, serviceID)
	if err != nil {
		return err
	}
	for _, candidate := range databases {
		if candidate.Name == database {
			return nil
		}
	}
	return fmt.Errorf("%w: database %q", ErrNotFound, database)
}

// resolveSite resolves a site id first and then its unique name.
func (m *Manager) resolveSite(ctx context.Context, ref string) (model.Site, error) {
	ref = strings.TrimSpace(ref)
	if ref == "" {
		return model.Site{}, fmt.Errorf("%w: site reference is empty", ErrInvalidRequest)
	}
	site, err := m.deps.Sites.GetSite(ctx, ref)
	if err == nil {
		return site, nil
	}
	if !errors.Is(err, store.ErrNotFound) {
		return model.Site{}, err
	}
	site, err = m.deps.Sites.GetSiteByName(ctx, strings.ToLower(ref))
	if err == nil {
		return site, nil
	}
	if !errors.Is(err, store.ErrNotFound) {
		return model.Site{}, err
	}
	return model.Site{}, fmt.Errorf("%w: site %q", ErrNotFound, ref)
}

// linkFromRecord assembles a link view without querying the engine.
func (m *Manager) linkFromRecord(_ context.Context, record model.DatabaseLinkRecord, user model.DatabaseUserRecord) model.DatabaseLink {
	serviceID := canonicalServiceID(record.ServiceID)
	engine := engineForService(serviceID)
	port := defaultServicePort(engine)
	link := model.DatabaseLink{
		ID:              record.ID,
		SiteID:          record.SiteID,
		SiteName:        record.SiteName,
		ServiceID:       serviceID,
		Engine:          engine,
		Database:        record.DatabaseName,
		UserID:          user.ID,
		Username:        user.Username,
		Host:            user.Host,
		Primary:         record.Primary,
		PasswordManaged: user.PasswordManaged,
		Available:       true,
		Connection: model.DatabaseConnection{
			Engine:          engine,
			Host:            "127.0.0.1",
			Port:            port,
			Database:        record.DatabaseName,
			Username:        user.Username,
			PasswordManaged: user.PasswordManaged,
		},
	}
	link.Connection.Env = metadataEnv(link)
	return link
}

// SiteEnv builds the safe, non-secret part of a site's database environment.
// The privileged platform adds password-bearing keys for managed links.
func SiteEnv(links []model.DatabaseLink) (map[string]string, error) {
	primaryIndex := -1
	for i, link := range links {
		if !link.Primary {
			continue
		}
		if primaryIndex >= 0 {
			return nil, fmt.Errorf("%w: multiple primary database links", ErrConflict)
		}
		primaryIndex = i
	}
	if primaryIndex < 0 && len(links) > 0 {
		primaryIndex = 0
	}
	env := make(map[string]string, len(links)*7)
	for i, link := range links {
		prefix := ""
		if i != primaryIndex {
			prefix = "DB_" + envSlug(link.Database) + "_"
		}
		engine := link.Engine
		if engine == "" {
			engine = link.Connection.Engine
		}
		port := link.Connection.Port
		if port == 0 {
			port = defaultServicePort(engine)
		}
		username := link.Username
		if username == "" {
			username = link.Connection.Username
		}
		env[prefix+"DB_CONNECTION"] = dbConnectionValue(engine)
		env[prefix+"DB_HOST"] = "127.0.0.1"
		env[prefix+"DB_PORT"] = fmt.Sprintf("%d", port)
		env[prefix+"DB_DATABASE"] = link.Database
		env[prefix+"DB_USERNAME"] = username
		if link.PasswordManaged && link.Connection.URL != "" {
			if prefix == "" {
				env["DATABASE_URL"] = link.Connection.URL
			} else {
				env[prefix+"URL"] = link.Connection.URL
			}
		}
	}
	return env, nil
}

// metadataEnv returns the non-secret environment keys for one link.
func metadataEnv(link model.DatabaseLink) map[string]string {
	engine := link.Engine
	if engine == "" {
		engine = link.Connection.Engine
	}
	port := link.Connection.Port
	if port == 0 {
		port = defaultServicePort(engine)
	}
	username := link.Username
	if username == "" {
		username = link.Connection.Username
	}
	return map[string]string{
		"DB_CONNECTION": dbConnectionValue(engine),
		"DB_HOST":       "127.0.0.1",
		"DB_PORT":       fmt.Sprintf("%d", port),
		"DB_DATABASE":   link.Database,
		"DB_USERNAME":   username,
	}
}

// envSlug converts a database name into an env-variable segment.
func envSlug(value string) string {
	slug := strings.ToUpper(strings.TrimSpace(value))
	slug = envSlugPattern.ReplaceAllString(slug, "_")
	slug = strings.Trim(slug, "_")
	if slug == "" {
		return "DB"
	}
	if slug[0] >= '0' && slug[0] <= '9' {
		return "DB_" + slug
	}
	return slug
}

// userHasGrant reports whether a user has any grant on a database.
func userHasGrant(user model.DatabaseUser, database string) bool {
	for _, grant := range user.Grants {
		if grant.Database == database {
			return true
		}
	}
	return false
}

package databases

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/AramZahedi/dev-web-stack/internal/model"
	"github.com/AramZahedi/dev-web-stack/internal/store"
)

// ProvisionSiteDatabase creates or reuses a database/user pair before a site
// row exists. It never grants access to an existing user.
func (m *Manager) ProvisionSiteDatabase(ctx context.Context, req SiteDatabaseRequest) (ProvisionedDatabase, error) {
	serviceID := canonicalServiceID(req.ServiceID)
	if isRedisService(serviceID) {
		return ProvisionedDatabase{}, fmt.Errorf("%w: Redis users cannot be linked to sites", ErrUnsupported)
	}
	if _, err := m.requireActive(ctx, serviceID); err != nil {
		return ProvisionedDatabase{}, err
	}
	if strings.TrimSpace(req.Password) != "" {
		return ProvisionedDatabase{}, fmt.Errorf("%w: the platform contract cannot store an external password; use a metadata-only link", ErrUnsupported)
	}
	req.ServiceID = serviceID

	var database model.Database
	var err error
	switch {
	case req.NewDatabase != nil:
		database, err = m.CreateDatabase(ctx, serviceID, *req.NewDatabase)
		if err != nil {
			return ProvisionedDatabase{}, err
		}
	case strings.TrimSpace(req.Database) != "":
		database, err = m.existingDatabase(ctx, serviceID, req.Database)
		if err != nil {
			return ProvisionedDatabase{}, err
		}
	default:
		return ProvisionedDatabase{}, fmt.Errorf("%w: choose an existing database or create a new one", ErrInvalidRequest)
	}

	var user model.DatabaseUser
	warning := ""
	switch {
	case req.NewUser != nil:
		create := *req.NewUser
		if len(create.Grants) == 0 {
			preset := req.Grant
			if preset == "" {
				preset = model.GrantReadWriteSchema
			}
			create.Grants = []model.DatabaseGrant{{Database: database.Name, Preset: preset}}
		}
		user, err = m.CreateUser(ctx, serviceID, create)
		if err != nil {
			return ProvisionedDatabase{}, err
		}
	case strings.TrimSpace(req.UserID) != "":
		user, err = m.existingUser(ctx, serviceID, req.UserID)
		if err != nil {
			return ProvisionedDatabase{}, err
		}
		if !userHasGrant(user, database.Name) {
			warning = fmt.Sprintf("database user %s has no grant on database %s; grant access before relying on this link", user.Username, database.Name)
		}
	default:
		return ProvisionedDatabase{}, fmt.Errorf("%w: choose an existing user or create a new one", ErrInvalidRequest)
	}

	return ProvisionedDatabase{
		Database: database,
		User:     user,
		Warning:  warning,
		Request:  req,
	}, nil
}

// LinkProvisioned creates the site link for a provisioned database/user pair.
// It never re-grants or recreates anything.
func (m *Manager) LinkProvisioned(ctx context.Context, siteID string, provisioned ProvisionedDatabase) (SiteDatabaseResult, error) {
	site, err := m.deps.Sites.GetSite(ctx, siteID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			return SiteDatabaseResult{}, fmt.Errorf("%w: site %q", ErrNotFound, siteID)
		}
		return SiteDatabaseResult{}, err
	}
	serviceID := canonicalServiceID(provisioned.Request.ServiceID)
	if serviceID == "" {
		serviceID = canonicalServiceID(provisioned.Database.ServiceID)
	}
	if serviceID == "" {
		return SiteDatabaseResult{}, fmt.Errorf("%w: service is required", ErrInvalidRequest)
	}
	unlock := m.lockService(serviceID)
	defer unlock()

	records, err := m.deps.Store.ListDatabaseLinksBySite(ctx, site.ID)
	if err != nil {
		return SiteDatabaseResult{}, err
	}
	primary := provisioned.Request.Primary
	if len(records) == 0 {
		primary = true
	}
	record := model.DatabaseLinkRecord{
		ID:           m.newID("lnk"),
		SiteID:       site.ID,
		SiteName:     site.Name,
		ServiceID:    serviceID,
		DatabaseName: provisioned.Database.Name,
		UserID:       provisioned.User.ID,
		Primary:      primary,
		CreatedAt:    m.now().Unix(),
	}
	if err := m.deps.Store.CreateDatabaseLink(ctx, record); err != nil {
		if errors.Is(err, store.ErrConflict) {
			return SiteDatabaseResult{}, fmt.Errorf("%w: database %q is already linked to site %q", ErrConflict, record.DatabaseName, site.Name)
		}
		return SiteDatabaseResult{}, err
	}
	if primary {
		if err := m.deps.Store.SetPrimaryDatabaseLink(ctx, site.ID, record.ID); err != nil {
			return SiteDatabaseResult{}, err
		}
	}
	link := m.linkFromRecord(ctx, record, model.DatabaseUserRecord{
		ID:              provisioned.User.ID,
		ServiceID:       provisioned.User.ServiceID,
		Engine:          provisioned.User.Engine,
		Username:        provisioned.User.Username,
		Host:            provisioned.User.Host,
		PasswordManaged: provisioned.User.PasswordManaged,
	})
	if provisioned.Warning != "" {
		link.Error = provisioned.Warning
	}
	m.audit(ctx, "database.link.changed", serviceID, site.ID, "database_link", record.DatabaseName, "ok", map[string]any{
		"link_id": record.ID, "user_id": provisioned.User.ID, "primary": primary,
	})
	m.emit(ctx, site.ID, "database.link.changed", fmt.Sprintf("site %s linked to database %s on %s", site.Name, record.DatabaseName, serviceID))
	return SiteDatabaseResult{
		Link:     link,
		Database: provisioned.Database,
		User:     provisioned.User,
		Warning:  provisioned.Warning,
	}, nil
}

// CreateSiteDatabase provisions and links a database for an existing site.
func (m *Manager) CreateSiteDatabase(ctx context.Context, siteRef string, req SiteDatabaseRequest) (SiteDatabaseResult, error) {
	site, err := m.resolveSite(ctx, siteRef)
	if err != nil {
		return SiteDatabaseResult{}, err
	}
	provisioned, err := m.ProvisionSiteDatabase(ctx, req)
	if err != nil {
		return SiteDatabaseResult{}, err
	}
	return m.LinkProvisioned(ctx, site.ID, provisioned)
}

// existingDatabase returns the live engine view for a database.
func (m *Manager) existingDatabase(ctx context.Context, serviceID, name string) (model.Database, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return model.Database{}, fmt.Errorf("%w: database is required", ErrInvalidRequest)
	}
	databases, err := m.deps.Platform.ListDatabases(ctx, serviceID)
	if err != nil {
		return model.Database{}, err
	}
	for _, database := range databases {
		if database.Name == name {
			if database.ServiceID == "" {
				database.ServiceID = serviceID
			}
			if database.Engine == "" {
				database.Engine = engineForService(serviceID)
			}
			return database, nil
		}
	}
	return model.Database{}, fmt.Errorf("%w: database %q", ErrNotFound, name)
}

// existingUser returns a user with live grants, falling back to persisted
// metadata when the engine inventory is unavailable.
func (m *Manager) existingUser(ctx context.Context, serviceID, userID string) (model.DatabaseUser, error) {
	users, err := m.ListUsers(ctx, serviceID)
	if err == nil {
		for _, user := range users {
			if user.ID == userID {
				return user, nil
			}
		}
		return model.DatabaseUser{}, fmt.Errorf("%w: user %q", ErrNotFound, userID)
	}
	record, storeErr := m.deps.Store.GetDatabaseUser(ctx, userID)
	if storeErr != nil {
		if errors.Is(storeErr, store.ErrNotFound) {
			return model.DatabaseUser{}, fmt.Errorf("%w: user %q", ErrNotFound, userID)
		}
		return model.DatabaseUser{}, storeErr
	}
	return m.userView(ctx, serviceID, record, nil), nil
}

