	platform.grants = nil
	result, err := m.CreateSiteDatabase(context.Background(), "blog", SiteDatabaseRequest{ServiceID: "mysql", Database: "app", UserID: "usr_app"})
	if err != nil {
		t.Fatal(err)
	}
	if result.Warning == "" {
		t.Fatal("missing access warning")
	}
	if len(platform.grantCalls) != 0 {
