	if _, err := a.CreateDatabase(context.Background(), "postgresql", databases.CreateDatabaseRequest{Name: "app"}); err != nil {
		t.Fatal(err)
	}
	if api.lastService != "postgres" {
		t.Fatalf("service id = %q, want postgres", api.lastService)
	}
}

