func NewAgentDocker(api serviceAgentAPI, wslRoot string) (*AgentDocker, error) {
	if api == nil {
		return nil, errors.New("servicecontrol: agent API is required")
	}
	paths, err := NewAgentPaths(wslRoot)
	if err != nil {
		return nil, err
	}
