func safeConnectionURL(engine model.DatabaseEngine, port int, database, username string) string {
	scheme := connectionScheme(engine)
	if scheme == "" || username == "" {
		return ""
	}
	return (&url.URL{
		Scheme: scheme,
		User:   url.User(username),
		Host:   fmt.Sprintf("127.0.0.1:%d", port),
		Path:   "/" + database,
	}).String()
}

